function on_request()
    if req.body_contains("route=canary;") then
        req.set_header("x-selected", "canary")
        return route.proxy("canary")
    end
    req.set_header("x-selected", "primary")
    return route.proxy("primary")
end

fixtures.header.rgl:
function on_request()
    if req.header("x-canary") == "1" then
        req.set_header("x-selected", "canary")
        return route.proxy("canary")
    end
    req.set_header("x-selected", "primary")
    return route.proxy("primary")
end

